package oidc

import (
	"crypto/subtle"
	"database/sql"
	"encoding/json"
	"errors"
	"strings"
	"time"

	"github.com/google/uuid"
	"golang.org/x/crypto/bcrypt"
	"idp/internal/config"
	"idp/internal/db"
	"idp/internal/token"
)

type Client struct{ID,Name string;SecretHash string;RedirectURIs,AllowedScopes,GrantTypes []string}
type Service struct{cfg config.Config;store *db.Store;tokens *token.Service}
func New(c config.Config,s *db.Store,t *token.Service)*Service{return &Service{c,s,t}}
func(s *Service)Client(id string)(Client,error){var c Client;var a,b,d string;e:=s.store.DB.QueryRow(`SELECT id,name,secret_hash,redirect_uris,allowed_scopes,grant_types FROM oidc_clients WHERE id=?`,id).Scan(&c.ID,&c.Name,&c.SecretHash,&a,&b,&d);if e!=nil{return c,e};_ = json.Unmarshal([]byte(a),&c.RedirectURIs);_ = json.Unmarshal([]byte(b),&c.AllowedScopes);_ = json.Unmarshal([]byte(d),&c.GrantTypes);return c,nil}
func(s *Service)AuthenticateClient(id,secret string)(Client,error){c,e:=s.Client(id);if e!=nil{return c,e};if bcrypt.CompareHashAndPassword([]byte(c.SecretHash),[]byte(secret))!=nil{return c,errors.New("invalid client")};return c,nil}
func(s *Service)CreateCode(uid,cid,redirect,scope,challenge,method,nonce string)(string,error){code:=uuid.NewString();now:=time.Now().UTC();_,e:=s.store.DB.Exec(`INSERT INTO oidc_sessions(id,user_id,client_id,scope,code_challenge,code_challenge_method,nonce,redirect_uri,expires_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)`,code,uid,cid,scope,challenge,method,nonce,redirect,now.Add(5*time.Minute),now);return code,e}
func(s *Service)ExchangeCode(c Client,code,redirect,verifier string)(map[string]any,error){var uid,scope,challenge,method,nonce,storedRedirect string;var expiry time.Time;e:=s.store.DB.QueryRow(`SELECT user_id,scope,code_challenge,code_challenge_method,nonce,redirect_uri,expires_at FROM oidc_sessions WHERE id=? AND client_id=?`,code,c.ID).Scan(&uid,&scope,&challenge,&method,&nonce,&storedRedirect,&expiry);if e!=nil||time.Now().After(expiry)||redirect!=storedRedirect{return nil,errors.New("invalid code")};if challenge!=""{candidate:=verifier;if method=="S256"{candidate=token.PKCE(verifier)};if subtle.ConstantTimeCompare([]byte(candidate),[]byte(challenge))!=1{return nil,errors.New("bad verifier")}}else if verifier!=""{return nil,errors.New("unexpected verifier")};_,_=s.store.DB.Exec(`DELETE FROM oidc_sessions WHERE id=?`,code);idToken,e:=s.tokens.IDToken(uid,c.ID,scope,nonce);if e!=nil{return nil,e};access,accessID,expires,e:=s.tokens.AccessToken(uid,c.ID,scope);if e!=nil{return nil,e};_,e=s.store.DB.Exec(`INSERT INTO access_tokens(jti,user_id,client_id,expires_at) VALUES(?,?,?,?)`,accessID,uid,c.ID,time.Now().Add(time.Duration(s.cfg.TokenTTL)*time.Second));if e!=nil{return nil,e};refresh:=uuid.NewString();_,e=s.store.DB.Exec(`INSERT INTO refresh_tokens(id,user_id,client_id,scope,expires_at,created_at) VALUES(?,?,?,?,?,?)`,refresh,uid,c.ID,scope,time.Now().Add(time.Duration(s.cfg.RefreshTTL)*time.Second),time.Now().UTC());if e!=nil{return nil,e};return map[string]any{"access_token":access,"token_type":"Bearer","expires_in":expires,"refresh_token":refresh,"id_token":idToken,"scope":scope},nil}
func(s *Service)Refresh(c Client,id string)(map[string]any,error){var uid,scope string;var exp time.Time;e:=s.store.DB.QueryRow(`SELECT user_id,scope,expires_at FROM refresh_tokens WHERE id=? AND client_id=? AND revoked=0`,id,c.ID).Scan(&uid,&scope,&exp);if e!=nil||time.Now().After(exp){return nil,errors.New("invalid refresh token")};_,_=s.store.DB.Exec(`UPDATE refresh_tokens SET revoked=1 WHERE id=?`,id);access,jti,ttl,e:=s.tokens.AccessToken(uid,c.ID,scope);if e!=nil{return nil,e};_,e=s.store.DB.Exec(`INSERT INTO access_tokens(jti,user_id,client_id,expires_at) VALUES(?,?,?,?)`,jti,uid,c.ID,time.Now().Add(time.Duration(s.cfg.TokenTTL)*time.Second));if e!=nil{return nil,e};next:=uuid.NewString();_,e=s.store.DB.Exec(`INSERT INTO refresh_tokens(id,user_id,client_id,scope,expires_at,created_at) VALUES(?,?,?,?,?,?)`,next,uid,c.ID,scope,time.Now().Add(time.Duration(s.cfg.RefreshTTL)*time.Second),time.Now().UTC());return map[string]any{"access_token":access,"token_type":"Bearer","expires_in":ttl,"refresh_token":next,"scope":scope},e}
func(s *Service)Login(login,password string)(string,error){var id,hash string;e:=s.store.DB.QueryRow(`SELECT id,password FROM users WHERE (email=? COLLATE NOCASE OR username=? COLLATE NOCASE) AND active=1`,login,login).Scan(&id,&hash);if e!=nil||bcrypt.CompareHashAndPassword([]byte(hash),[]byte(password))!=nil{return "",errors.New("invalid login")};return id,nil}
func(s *Service)ChangePassword(id,current,next string)error{var hash string;if e:=s.store.DB.QueryRow(`SELECT password FROM users WHERE id=?`,id).Scan(&hash);e!=nil{return e};if bcrypt.CompareHashAndPassword([]byte(hash),[]byte(current))!=nil{return errors.New("invalid password")};h,e:=bcrypt.GenerateFromPassword([]byte(next),12);if e!=nil{return e};_,e=s.store.DB.Exec(`UPDATE users SET password=?,updated_at=? WHERE id=?`,string(h),time.Now().UTC(),id);return e}
func(s *Service)UserInfo(id string)(map[string]any,error){var username,email,name string;e:=s.store.DB.QueryRow(`SELECT username,email,display_name FROM users WHERE id=? AND active=1`,id).Scan(&username,&email,&name);if e!=nil{return nil,e};roles,groups:=[]string{},[]string{};rows,e:=s.store.DB.Query(`SELECT role FROM user_roles WHERE user_id=? ORDER BY role`,id);if e!=nil{return nil,e};for rows.Next(){var x string;if e=rows.Scan(&x);e!=nil{_ = rows.Close();return nil,e};roles=append(roles,x)};if e=rows.Err();e!=nil{_ = rows.Close();return nil,e};_ = rows.Close();rows,e=s.store.DB.Query(`SELECT group_name FROM user_groups WHERE user_id=? ORDER BY group_name`,id);if e!=nil{return nil,e};for rows.Next(){var x string;if e=rows.Scan(&x);e!=nil{_ = rows.Close();return nil,e};groups=append(groups,x)};if e=rows.Err();e!=nil{_ = rows.Close();return nil,e};_ = rows.Close();return map[string]any{"sub":id,"email":email,"email_verified":true,"preferred_username":username,"name":name,"picture":strings.TrimRight(s.cfg.BaseURL,"/")+"/api/v1/users/"+username+"/avatar","roles":roles,"groups":groups},nil}
func(s *Service)ClientByID(id string)(bool){var n int;_ = s.store.DB.QueryRow(`SELECT count(*) FROM oidc_clients WHERE id=?`,id).Scan(&n);return n==1}
var _=sql.ErrNoRows
